import sys

data = sys.stdin.read().split()
n = int(data[0])
m = int(data[1])
edges = [tuple(map(int, data[2 + i * 2:4 + i * 2])) for i in range(m)]
r = [[False] * (n + 1) for _ in range(n + 1)]
for i in range(1, n + 1):
    r[i][i] = True
for u, v in edges:
    r[u][v] = True
for k in range(1, n + 1):
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if r[i][k] and r[k][j]:
                r[i][j] = True
seen = [False] * (n + 1)
c = 0
for i in range(1, n + 1):
    if not seen[i]:
        c += 1
        for j in range(1, n + 1):
            if r[i][j] and r[j][i]:
                seen[j] = True
print(c)

